PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, phone TEXT, email TEXT, address TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, phone TEXT, email TEXT, address TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN('MATERIAL','PRODUCT','EXPENSE')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS code_base (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, entity_type TEXT NOT NULL CHECK(entity_type IN('MATERIAL','PRODUCT','COMBO')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS raw_materials (id INTEGER PRIMARY KEY AUTOINCREMENT, code_base_id INTEGER NOT NULL UNIQUE REFERENCES code_base(id), category_id INTEGER REFERENCES categories(id), unit TEXT NOT NULL, current_stock REAL NOT NULL DEFAULT 0 CHECK(current_stock>=0), minimum_stock REAL NOT NULL DEFAULT 0 CHECK(minimum_stock>=0), current_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(current_cost_cents>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS raw_material_purchases (id INTEGER PRIMARY KEY AUTOINCREMENT, operation_key TEXT NOT NULL UNIQUE, material_id INTEGER NOT NULL REFERENCES raw_materials(id), supplier_id INTEGER REFERENCES suppliers(id), quantity REAL NOT NULL CHECK(quantity>0), total_cost_cents INTEGER NOT NULL CHECK(total_cost_cents>=0), unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), purchased_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, code_base_id INTEGER NOT NULL UNIQUE REFERENCES code_base(id), category_id INTEGER REFERENCES categories(id), type TEXT NOT NULL CHECK(type IN('MANUFACTURED','COMBO')), sale_price_cents INTEGER NOT NULL DEFAULT 0 CHECK(sale_price_cents>=0), estimated_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(estimated_cost_cents>=0), current_stock REAL NOT NULL DEFAULT 0 CHECK(current_stock>=0), minimum_stock REAL NOT NULL DEFAULT 0 CHECK(minimum_stock>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS recipes (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL UNIQUE REFERENCES products(id), yield_quantity REAL NOT NULL DEFAULT 1 CHECK(yield_quantity>0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS recipe_items (id INTEGER PRIMARY KEY AUTOINCREMENT, recipe_id INTEGER NOT NULL REFERENCES recipes(id) ON DELETE CASCADE, material_id INTEGER NOT NULL REFERENCES raw_materials(id), quantity_per_yield REAL NOT NULL CHECK(quantity_per_yield>0), UNIQUE(recipe_id,material_id));
CREATE TABLE IF NOT EXISTS combos (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL UNIQUE REFERENCES products(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS combo_recipe_items (id INTEGER PRIMARY KEY AUTOINCREMENT, combo_id INTEGER NOT NULL REFERENCES combos(id) ON DELETE CASCADE, component_product_id INTEGER NOT NULL REFERENCES products(id), quantity REAL NOT NULL CHECK(quantity>0), UNIQUE(combo_id,component_product_id));
CREATE TABLE IF NOT EXISTS manufacturing_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, operation_key TEXT NOT NULL UNIQUE, product_id INTEGER NOT NULL REFERENCES products(id), quantity REAL NOT NULL CHECK(quantity>0), total_cost_cents INTEGER NOT NULL CHECK(total_cost_cents>=0), unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), manufactured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE IF NOT EXISTS manufacturing_materials (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id INTEGER NOT NULL REFERENCES manufacturing_batches(id) ON DELETE CASCADE, material_id INTEGER NOT NULL REFERENCES raw_materials(id), quantity_used REAL NOT NULL CHECK(quantity_used>0), frozen_unit_cost_cents INTEGER NOT NULL CHECK(frozen_unit_cost_cents>=0), frozen_total_cost_cents INTEGER NOT NULL CHECK(frozen_total_cost_cents>=0));
CREATE TABLE IF NOT EXISTS combo_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, operation_key TEXT NOT NULL UNIQUE, combo_id INTEGER NOT NULL REFERENCES combos(id), quantity REAL NOT NULL CHECK(quantity>0), total_cost_cents INTEGER NOT NULL CHECK(total_cost_cents>=0), unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), assembled_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE IF NOT EXISTS combo_batch_items (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id INTEGER NOT NULL REFERENCES combo_batches(id) ON DELETE CASCADE, component_product_id INTEGER NOT NULL REFERENCES products(id), quantity_used REAL NOT NULL CHECK(quantity_used>0), frozen_unit_cost_cents INTEGER NOT NULL CHECK(frozen_unit_cost_cents>=0), frozen_total_cost_cents INTEGER NOT NULL CHECK(frozen_total_cost_cents>=0));
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY AUTOINCREMENT, operation_key TEXT NOT NULL UNIQUE, client_id INTEGER REFERENCES clients(id), total_cents INTEGER NOT NULL CHECK(total_cents>=0), total_cost_cents INTEGER NOT NULL CHECK(total_cost_cents>=0), profit_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'PAID' CHECK(status IN('PAID','PENDING','CANCELLED')), sold_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY AUTOINCREMENT, sale_id INTEGER NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), quantity REAL NOT NULL CHECK(quantity>0), frozen_unit_price_cents INTEGER NOT NULL CHECK(frozen_unit_price_cents>=0), frozen_unit_cost_cents INTEGER NOT NULL CHECK(frozen_unit_cost_cents>=0), line_total_cents INTEGER NOT NULL CHECK(line_total_cents>=0), line_cost_cents INTEGER NOT NULL CHECK(line_cost_cents>=0));
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, category_id INTEGER REFERENCES categories(id), supplier_id INTEGER REFERENCES suppliers(id), description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), incurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, operation_key TEXT NOT NULL, entity_type TEXT NOT NULL CHECK(entity_type IN('MATERIAL','PRODUCT')), material_id INTEGER REFERENCES raw_materials(id), product_id INTEGER REFERENCES products(id), movement_type TEXT NOT NULL CHECK(movement_type IN('PURCHASE','MANUFACTURE_INPUT','MANUFACTURE_OUTPUT','COMBO_INPUT','COMBO_OUTPUT','SALE','ADJUSTMENT')), quantity_delta REAL NOT NULL CHECK(quantity_delta<>0), balance_after REAL NOT NULL CHECK(balance_after>=0), unit_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(unit_cost_cents>=0), reference_table TEXT NOT NULL, reference_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((entity_type='MATERIAL' AND material_id IS NOT NULL AND product_id IS NULL) OR (entity_type='PRODUCT' AND product_id IS NOT NULL AND material_id IS NULL)));
CREATE TABLE IF NOT EXISTS monthly_profits (id INTEGER PRIMARY KEY AUTOINCREMENT, month TEXT NOT NULL UNIQUE, sales_cents INTEGER NOT NULL DEFAULT 0, product_cost_cents INTEGER NOT NULL DEFAULT 0, expense_cents INTEGER NOT NULL DEFAULT 0, profit_cents INTEGER NOT NULL DEFAULT 0, calculated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profit_history (id INTEGER PRIMARY KEY AUTOINCREMENT, month TEXT NOT NULL, sales_cents INTEGER NOT NULL, product_cost_cents INTEGER NOT NULL, expense_cents INTEGER NOT NULL, profit_cents INTEGER NOT NULL, captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reason TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_movements_operation ON stock_movements(operation_key);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(sold_at);
CREATE INDEX IF NOT EXISTS idx_purchases_date ON raw_material_purchases(purchased_at);
CREATE INDEX IF NOT EXISTS idx_expenses_date ON expenses(incurred_at);
DROP TABLE IF EXISTS app_state;
